-- =====================================================================
-- 0004_business_write_policies.sql
-- =====================================================================
-- Town Hub Rewards — Phase 2: employees, business_registration_codes,
-- and the real (non-stub) business-owner RLS policies that replace the
-- commented Phase-1 stubs. Apply via Supabase SQL Editor, after 0003.

-- ---------------------------------------------------------------------
-- employees
-- Staff sub-accounts under a business, distinct from the owner. role is
-- free text (not an enum) — same reasoning offer_type already applied:
-- Phase 2 only needs 'staff', and an enum would mean an ALTER TYPE for
-- any future tier. No UI creates rows here yet (Settings/Employees
-- screen is explicitly out of scope this pass) — the table/RLS exist so
-- that screen is a pure UI increment later, no further schema work.
-- ---------------------------------------------------------------------
create table public.employees (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses(id) on delete cascade,
  profile_id uuid not null references public.profiles(id) on delete cascade,
  role text not null default 'staff',
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  unique (business_id, profile_id)
);

create index employees_business_id_idx on public.employees (business_id);
create index employees_profile_id_idx on public.employees (profile_id);

-- ---------------------------------------------------------------------
-- business_registration_codes
-- Admin-minted, single-use codes tied to a specific pre-created business
-- row. The admin creates the business first, then mints a code for it —
-- register-business attaches the caller as owner to that existing row
-- rather than inserting a new business, avoiding a duplicate-row bug.
-- business_name_hint is a denormalized display convenience for the
-- admin UI, not authoritative — businesses.name is.
-- ---------------------------------------------------------------------
create table public.business_registration_codes (
  code text primary key,
  business_id uuid not null references public.businesses(id) on delete cascade,
  is_used boolean not null default false,
  business_name_hint text,
  created_at timestamptz not null default now(),
  used_at timestamptz,
  used_by uuid references public.profiles(id)
);

create index business_registration_codes_business_id_idx
  on public.business_registration_codes (business_id);

-- ---------------------------------------------------------------------
-- Helper: is the caller the owner OR an active staff member of the given
-- business? Centralizes the two-table exists() so every member-scoped
-- SELECT policy below (and future ones) stays a one-liner.
-- ---------------------------------------------------------------------
create or replace function public.is_business_member(target_business_id uuid)
returns boolean
language sql
stable
security definer set search_path = public
as $$
  select exists (
    select 1 from public.businesses b
    where b.id = target_business_id and b.owner_id = auth.uid()
  ) or exists (
    select 1 from public.employees e
    where e.business_id = target_business_id and e.profile_id = auth.uid() and e.is_active = true
  );
$$;

-- ---------------------------------------------------------------------
-- Atomically attach a caller as owner of the business a code unlocks.
-- Wrapped in a single Postgres function (not sequential JS calls from
-- the Edge Function) because this touches three tables and genuinely
-- needs transactional atomicity — a partial failure (code marked used
-- but business never claimed) would be a real correctness bug, not
-- just a UX nit.
-- ---------------------------------------------------------------------
create or replace function public.register_business_with_code(p_code text, p_owner_id uuid)
returns public.businesses
language plpgsql
security definer set search_path = public
as $$
declare
  v_business_id uuid;
  v_updated int;
  v_business public.businesses;
begin
  select business_id into v_business_id
    from public.business_registration_codes
    where code = p_code;

  if v_business_id is null then
    raise exception 'INVALID_CODE';
  end if;

  if exists (select 1 from public.businesses where id = v_business_id and owner_id is not null) then
    raise exception 'BUSINESS_ALREADY_CLAIMED';
  end if;

  update public.business_registration_codes
    set is_used = true, used_at = now(), used_by = p_owner_id
    where code = p_code and is_used = false;
  get diagnostics v_updated = row_count;
  if v_updated = 0 then
    raise exception 'CODE_ALREADY_USED';
  end if;

  update public.businesses
    set owner_id = p_owner_id
    where id = v_business_id
    returning * into v_business;

  update public.profiles set role = 'business_owner' where id = p_owner_id;

  return v_business;
end;
$$;

-- Only register-business's service-role client may call this — same
-- "server-side only" pattern the whole schema uses for token writes.
revoke execute on function public.register_business_with_code(text, uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- RLS: enable on new tables
-- ---------------------------------------------------------------------
alter table public.employees enable row level security;
alter table public.business_registration_codes enable row level security;

create policy "employees_owner_manage"
  on public.employees for all
  to authenticated
  using (exists (select 1 from public.businesses b where b.id = business_id and b.owner_id = auth.uid()))
  with check (exists (select 1 from public.businesses b where b.id = business_id and b.owner_id = auth.uid()));

create policy "employees_self_select"
  on public.employees for select
  to authenticated
  using (profile_id = auth.uid());

-- No policies on business_registration_codes for `authenticated` here —
-- register-business's service-role client (bypasses RLS) is the only
-- authenticated-context reader/writer until 0005 adds admin policies.

-- ---------------------------------------------------------------------
-- businesses / branches / offers: replace the Phase 1 stub comments.
-- Split owner "manage" (all commands) from a separate member "select"
-- (owner+employee) — NOT combined into one `for all` using
-- is_business_member(), because Postgres RLS only evaluates USING for
-- DELETE (not WITH CHECK), so a combined policy would let employees
-- delete rows. Splitting keeps staff strictly read-only.
-- ---------------------------------------------------------------------
create policy "businesses_owner_manage"
  on public.businesses for all
  to authenticated
  using (owner_id = auth.uid())
  with check (owner_id = auth.uid());

create policy "businesses_member_select"
  on public.businesses for select
  to authenticated
  using (public.is_business_member(id));

create policy "branches_owner_manage"
  on public.branches for all
  to authenticated
  using (exists (select 1 from public.businesses b where b.id = business_id and b.owner_id = auth.uid()))
  with check (exists (select 1 from public.businesses b where b.id = business_id and b.owner_id = auth.uid()));

create policy "branches_member_select"
  on public.branches for select
  to authenticated
  using (public.is_business_member(business_id));

create policy "offers_owner_manage"
  on public.offers for all
  to authenticated
  using (exists (select 1 from public.businesses b where b.id = business_id and b.owner_id = auth.uid()))
  with check (exists (select 1 from public.businesses b where b.id = business_id and b.owner_id = auth.uid()));

create policy "offers_member_select"
  on public.offers for select
  to authenticated
  using (public.is_business_member(business_id));

-- ---------------------------------------------------------------------
-- redemption_tokens / redemptions: business owner+staff read-only, for
-- the new business app's /redemptions page (a plain RLS-scoped client
-- read, matching lib/rewards/queries.ts's style rather than routing
-- through an Edge Function). No write policy — writes stay
-- service-role-only via approve-redemption, unchanged from Phase 1.
-- ---------------------------------------------------------------------
create policy "redemption_tokens_business_select"
  on public.redemption_tokens for select
  to authenticated
  using (public.is_business_member(business_id));

create policy "redemptions_business_select"
  on public.redemptions for select
  to authenticated
  using (public.is_business_member(business_id));

-- =====================================================================
-- 0005_admin_policies.sql
-- =====================================================================
-- Town Hub Rewards — Phase 3: admin RLS. Apply after 0004.

create or replace function public.is_admin()
returns boolean
language sql
stable
security definer set search_path = public
as $$
  select exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin');
$$;

-- profiles: admin reads everyone (customer/business lists). No admin
-- UPDATE policy yet — role/is_subscribed/suspend changes stay SQL-Editor-
-- only until a dedicated Edge Function exists (same deferral Phase 1
-- already made for is_subscribed, for the same reason).
create policy "profiles_admin_select"
  on public.profiles for select to authenticated using (public.is_admin());

-- businesses: admin reads all + creates new business rows (the
-- /admin/businesses "create business" step, ahead of any code
-- redemption). No admin UPDATE/DELETE — suspending a business is
-- explicitly deferred.
create policy "businesses_admin_select"
  on public.businesses for select to authenticated using (public.is_admin());
create policy "businesses_admin_insert"
  on public.businesses for insert to authenticated with check (public.is_admin());

create policy "branches_admin_select"
  on public.branches for select to authenticated using (public.is_admin());

-- offers: admin full manage across every business — powers
-- /admin/offers create/edit/toggle-active. Owner's own offers_owner_manage
-- policy from 0004 still applies independently for the owner's own writes.
create policy "offers_admin_manage"
  on public.offers for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- redemption_tokens: admin read-only (debugging/support visibility).
create policy "redemption_tokens_admin_select"
  on public.redemption_tokens for select to authenticated using (public.is_admin());

-- redemptions: admin read-only — powers /admin/redemptions. No write/
-- delete policy — "cancel a fraudulent redemption" needs a dedicated
-- Edge Function to also safely reverse the token, deferred per scope.
create policy "redemptions_admin_select"
  on public.redemptions for select to authenticated using (public.is_admin());

create policy "employees_admin_select"
  on public.employees for select to authenticated using (public.is_admin());

-- business_registration_codes: admin reads (outstanding/used codes) and
-- inserts (mints a code from /admin/businesses). No update/delete for
-- `authenticated` — a code is only ever marked used by
-- register-business's service-role client.
create policy "business_registration_codes_admin_select"
  on public.business_registration_codes for select to authenticated using (public.is_admin());
create policy "business_registration_codes_admin_insert"
  on public.business_registration_codes for insert to authenticated with check (public.is_admin());

-- =====================================================================
-- 0006_business_self_registration.sql
-- =====================================================================
-- Town Hub Rewards — Phase 4: self-serve business registration.
-- Lets a signed-in customer register their own business (pending admin
-- approval) instead of requiring an admin to pre-create it and mint a
-- registration code first. The admin-issued-code path from 0004 still
-- works unchanged and coexists with this one. Apply after 0005.

-- ---------------------------------------------------------------------
-- businesses: split the Phase 2 "owner manage" policy so INSERT isn't
-- bundled in with UPDATE/DELETE. Self-registration needs its own INSERT
-- policy that forces is_active = false (pending review) — a single
-- `for all using(owner_id = auth.uid())` policy can't express that,
-- since `using` doesn't constrain new rows, so it would let an owner
-- insert is_active = true directly and skip moderation entirely.
-- ---------------------------------------------------------------------
drop policy "businesses_owner_manage" on public.businesses;

create policy "businesses_owner_update"
  on public.businesses for update
  to authenticated
  using (owner_id = auth.uid())
  with check (owner_id = auth.uid());

create policy "businesses_self_register"
  on public.businesses for insert
  to authenticated
  with check (owner_id = auth.uid() and is_active = false);

-- Admin can now flip is_active to approve a pending self-registered
-- business (Phase 1-3 only ever gave admin SELECT/INSERT on businesses).
create policy "businesses_admin_update"
  on public.businesses for update
  to authenticated
  using (public.is_admin())
  with check (public.is_admin());

-- ---------------------------------------------------------------------
-- Promote a self-registering customer to business_owner the moment their
-- business row lands, mirroring what register_business_with_code already
-- does for the admin-code path. Guarded to role = 'customer' so it never
-- downgrades an admin/employee who happens to own a business row.
-- ---------------------------------------------------------------------
create or replace function public.handle_new_business_owner()
returns trigger
language plpgsql
security definer set search_path = public
as $$
begin
  if new.owner_id is not null then
    update public.profiles
      set role = 'business_owner'
      where id = new.owner_id and role = 'customer';
  end if;
  return new;
end;
$$;

create trigger on_business_insert_promote_owner
  after insert on public.businesses
  for each row execute function public.handle_new_business_owner();

-- =====================================================================
-- 0007_profile_self_update.sql
-- =====================================================================
-- Lets a signed-in user edit their own display name — and nothing else.
--
-- 0003 deferred this deliberately, noting there was "no safe column-level
-- RLS trick for 'user can edit full_name but not is_subscribed'". There is
-- one, it just isn't RLS: RLS chooses the ROW, a column-level GRANT chooses
-- the COLUMNS. Both are needed here.
--
-- With only a row policy, this would be a privilege-escalation hole —
--   update profiles set role = 'admin' where id = auth.uid()
-- satisfies `id = auth.uid()` and would succeed. The grant below is what
-- actually stops it: `authenticated` simply has no UPDATE privilege on
-- role, is_subscribed, id or the timestamps, so those columns are rejected
-- before any policy is consulted.

revoke update on public.profiles from authenticated;
grant update (full_name) on public.profiles to authenticated;

create policy "profiles_update_own"
  on public.profiles for update
  to authenticated
  using (id = auth.uid())
  with check (id = auth.uid());

-- updated_at is not writable by the user (see the grant above), so it has
-- to be maintained server-side or it would stay frozen at signup time.
create or replace function public.touch_profile_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists profiles_set_updated_at on public.profiles;
create trigger profiles_set_updated_at
  before update on public.profiles
  for each row execute function public.touch_profile_updated_at();

-- =====================================================================
-- 0008_profile_details.sql
-- =====================================================================
-- Gives a profile the details a member actually recognises as "their
-- account": an avatar, a home town and a contact number, alongside the
-- display name 0007 made editable.
--
-- avatar stores an id from components/Avatar.tsx (e.g. 'whale'), not a URL
-- or an image. The app ships offline inside a WebView, so an uploaded photo
-- would need storage, connectivity and a signed URL to render — none of
-- which exist on a plane or in a reception dead-spot. A picked avatar is a
-- short string that renders from bundled SVG and always works.
--
-- home_town stores a town slug from lib/garden-route/towns.ts. Deliberately
-- a plain text column rather than a foreign key: the gazetteer is generated
-- from OpenStreetMap and regenerating it must not be able to fail on a
-- constraint, or break someone's profile because a slug was renamed.

alter table public.profiles
  add column if not exists avatar text,
  add column if not exists home_town text,
  add column if not exists phone text;

-- Same split as 0007: the policy picks the row, the grant picks the
-- columns. Re-granting full_name alongside the new ones because a column
-- grant replaces the previous list for these columns rather than adding to
-- it, and leaving it out would silently make the name read-only again.
grant update (full_name, avatar, home_town, phone) on public.profiles to authenticated;

-- =====================================================================
-- 0009_avatar_uploads.sql
-- =====================================================================
-- Photo avatars: a storage bucket for uploaded profile pictures, plus the
-- column that points at one.
--
-- Why a public bucket. The app renders avatars inside an offline WebView
-- with no server to mint signed URLs, and a signed URL expires — a cached
-- profile picture would turn into a broken image the moment the signature
-- aged out. Public read keeps the URL stable and cacheable. Nothing secret
-- lives here: it is a picture the member chose to show other members.
--
-- Writes are not public. The policies below scope insert/update/delete to
-- the signed-in user's own folder, so <uid>/avatar.jpg can only be written
-- by that uid. Without the folder check any authenticated user could
-- overwrite anyone's picture.

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'avatars',
  'avatars',
  true,
  2097152, -- 2 MB. The client downscales to ~256px before upload, so a file
           -- anywhere near this ceiling means something bypassed that path.
  array['image/jpeg', 'image/png', 'image/webp']
)
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- storage.foldername(name)[1] is the first path segment: the owner's uid.
drop policy if exists "avatars_public_read" on storage.objects;
create policy "avatars_public_read"
  on storage.objects for select
  using (bucket_id = 'avatars');

drop policy if exists "avatars_insert_own" on storage.objects;
create policy "avatars_insert_own"
  on storage.objects for insert to authenticated
  with check (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

drop policy if exists "avatars_update_own" on storage.objects;
create policy "avatars_update_own"
  on storage.objects for update to authenticated
  using (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

drop policy if exists "avatars_delete_own" on storage.objects;
create policy "avatars_delete_own"
  on storage.objects for delete to authenticated
  using (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

-- avatar_url holds the public URL of an uploaded photo. It takes precedence
-- over the picked `avatar` illustration, and clearing it falls back to that
-- illustration rather than leaving the member with nothing.
alter table public.profiles
  add column if not exists avatar_url text;

-- Same split as 0007/0008: policy picks the row, grant picks the columns,
-- and the full list has to be restated because a column grant replaces it.
grant update (full_name, avatar, home_town, phone, avatar_url) on public.profiles to authenticated;

-- =====================================================================
-- 0010_legal_notices.sql
-- =====================================================================
-- Legal Notices: deceased estates, claims, liquidations, insolvencies and
-- tenders, published for attorneys and law firms. Apply after 0009.
--
-- Firms send notices to info@seaexpress.co.za and an admin publishes them
-- from /admin/notices, so there is no public insert path.

create table if not exists public.legal_notices (
  id uuid primary key default gen_random_uuid(),
  category text not null check (
    category in ('deceased_estate', 'claim', 'liquidation', 'insolvency', 'tender')
  ),
  title text not null,
  body text not null,
  -- Town slug from lib/garden-route/towns.ts; null for region-wide notices.
  town text,
  firm_name text,
  -- Estate number, case number or tender reference.
  reference text,
  contact text,
  published_on date not null default current_date,
  -- Last day to lodge claims / submit tenders; null when not applicable.
  closes_on date,
  is_active boolean not null default true,
  created_by uuid references public.profiles (id) on delete set null default auth.uid(),
  created_at timestamptz not null default now()
);

create index if not exists legal_notices_category_published_idx
  on public.legal_notices (category, published_on desc);

alter table public.legal_notices enable row level security;

-- Notices are public by nature, so anyone — signed in or not — reads the
-- active ones.
create policy "legal_notices_public_select"
  on public.legal_notices for select to anon, authenticated using (is_active);

-- Admins see inactive notices too and manage everything.
create policy "legal_notices_admin_manage"
  on public.legal_notices for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- =====================================================================
-- 0011_business_rewards_portal.sql
-- =====================================================================
-- Town Hub Rewards — Business Rewards Portal. Apply after 0010.
--
-- Fixes four defects in the 0003–0006 rewards backend and adds what the
-- Business Rewards Portal brief needs:
--
--   1. A business owner could UPDATE every column of their own business,
--      including is_active — so a pending or suspended business could switch
--      itself on. Approval and subscription columns are now admin-only.
--   2. offers_owner_manage let an owner publish offers directly. Offers now
--      go draft → submitted → approved/rejected, and only Town Hub approves.
--   3. Redemption claimed the token and inserted the redemption as two
--      separate writes, so a failure between them burned the voucher with
--      no record. It is now one transaction in redeem_voucher().
--   4. The reward month was computed in UTC, so 00:00–02:00 SAST on the 1st
--      still counted as the previous month. Periods now use
--      Africa/Johannesburg.
--
-- New: full company registration + eligibility (approval and paid
-- advertiser status), a short voucher code staff can type, a configurable
-- monthly limit per offer, and voucher snapshots of the offer's terms.
--
-- Apply via the Supabase SQL Editor, then redeploy the redeem-offer and
-- approve-redemption Edge Functions, which call the functions below.

-- ---------------------------------------------------------------------
-- Reward month, in South African time
-- ---------------------------------------------------------------------
create or replace function public.current_reward_period()
returns date
language sql
stable
as $$
  select date_trunc('month', now() at time zone 'Africa/Johannesburg')::date;
$$;

-- ---------------------------------------------------------------------
-- businesses: registration details and eligibility
-- ---------------------------------------------------------------------
alter table public.businesses
  add column if not exists registered_name text,
  add column if not exists trading_name text,
  add column if not exists registration_number text,
  -- "<source>:<id>" of the business's listing in the app's directories,
  -- e.g. 'business:mb-12' or 'restaurant:geo-3'.
  add column if not exists directory_listing_id text,
  add column if not exists contact_name text,
  add column if not exists phone text,
  add column if not exists email text,
  add column if not exists address text,
  add column if not exists town text,
  add column if not exists advertising_reference text,
  add column if not exists terms_accepted_at timestamptz,
  add column if not exists approval_status text not null default 'pending'
    check (approval_status in ('pending', 'approved', 'denied', 'suspended')),
  add column if not exists approval_note text,
  add column if not exists advertiser_status text not null default 'needs_verification'
    check (advertiser_status in ('active', 'expired', 'not_advertiser', 'needs_verification')),
  add column if not exists advertising_paid_until date,
  add column if not exists reviewed_at timestamptz,
  add column if not exists reviewed_by uuid references public.profiles(id) on delete set null;

-- Businesses already switched on were approved by hand before this
-- workflow existed; keep them working.
update public.businesses
  set approval_status = 'approved', advertiser_status = 'active'
  where is_active and approval_status = 'pending';

-- Duplicate registrations: one record per company and per directory listing.
create unique index if not exists businesses_registration_number_key
  on public.businesses (lower(registration_number)) where registration_number is not null;
create unique index if not exists businesses_directory_listing_key
  on public.businesses (directory_listing_id) where directory_listing_id is not null;

-- A business may run rewards only while approved by Town Hub AND a paying
-- advertiser whose subscription has not lapsed.
create or replace function public.business_is_eligible(p_business_id uuid)
returns boolean
language sql
stable
security definer set search_path = public
as $$
  select exists (
    select 1 from public.businesses b
    where b.id = p_business_id
      and b.is_active
      and b.approval_status = 'approved'
      and b.advertiser_status = 'active'
      and (b.advertising_paid_until is null
           or b.advertising_paid_until >= (now() at time zone 'Africa/Johannesburg')::date)
  );
$$;

-- Fix 1. Owners may edit their contact details, never their approval or
-- subscription standing. is_active is derived from approval_status so the
-- two cannot disagree. auth.role() is 'service_role' inside Edge Functions,
-- which are trusted and pass through.
create or replace function public.guard_business_write()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'authenticated' and not public.is_admin() then
    if tg_op = 'INSERT' then
      if exists (select 1 from public.businesses where owner_id = new.owner_id) then
        raise exception 'ALREADY_REGISTERED' using errcode = '23505';
      end if;
      if coalesce(trim(new.registered_name), '') = ''
        or coalesce(trim(new.registration_number), '') = ''
        or coalesce(trim(new.contact_name), '') = ''
        or coalesce(trim(new.phone), '') = ''
        or coalesce(trim(new.email), '') = ''
        or new.terms_accepted_at is null then
        raise exception 'INCOMPLETE_REGISTRATION' using errcode = '23514';
      end if;
      new.approval_status := 'pending';
      new.advertiser_status := 'needs_verification';
      new.advertising_paid_until := null;
      new.approval_note := null;
      new.reviewed_at := null;
      new.reviewed_by := null;
    elsif new.approval_status is distinct from old.approval_status
      or new.advertiser_status is distinct from old.advertiser_status
      or new.advertising_paid_until is distinct from old.advertising_paid_until
      or new.approval_note is distinct from old.approval_note
      or new.reviewed_at is distinct from old.reviewed_at
      or new.reviewed_by is distinct from old.reviewed_by
      or new.owner_id is distinct from old.owner_id
      or new.is_active is distinct from old.is_active
      or new.registration_number is distinct from old.registration_number then
      raise exception 'NOT_ALLOWED: only Town Hub can change approval or subscription status'
        using errcode = '42501';
    end if;
  end if;

  new.is_active := (new.approval_status = 'approved');
  return new;
end;
$$;

drop trigger if exists businesses_guard_write on public.businesses;
create trigger businesses_guard_write
  before insert or update on public.businesses
  for each row execute function public.guard_business_write();

-- Owners read their own business row directly. 0006 dropped the owner's
-- `for all` policy and left only is_business_member() for SELECT, which
-- can't see a row inserted by the same statement — so registering (an
-- INSERT ... RETURNING) always failed with an RLS error.
drop policy if exists "businesses_owner_select" on public.businesses;
create policy "businesses_owner_select"
  on public.businesses for select to authenticated
  using (owner_id = auth.uid());

-- A denied applicant can correct their details and apply again.
create or replace function public.resubmit_business_application()
returns void
language plpgsql
security definer set search_path = public
as $$
begin
  update public.businesses
    set approval_status = 'pending', approval_note = null, reviewed_at = null, reviewed_by = null
    where owner_id = auth.uid() and approval_status = 'denied';
  if not found then
    raise exception 'NOTHING_TO_RESUBMIT';
  end if;
end;
$$;

revoke execute on function public.resubmit_business_application() from public, anon;
grant execute on function public.resubmit_business_application() to authenticated;

-- ---------------------------------------------------------------------
-- offers: approval workflow and monthly limit
-- ---------------------------------------------------------------------
alter table public.offers
  add column if not exists status text not null default 'draft'
    check (status in ('draft', 'submitted', 'approved', 'rejected')),
  -- Redemptions allowed per customer, per offer, per calendar month.
  add column if not exists monthly_limit integer not null default 1
    check (monthly_limit between 1 and 31),
  add column if not exists purchase_conditions text,
  add column if not exists review_note text,
  add column if not exists submitted_at timestamptz,
  add column if not exists reviewed_at timestamptz,
  add column if not exists reviewed_by uuid references public.profiles(id) on delete set null;

-- Every existing offer was created by an admin and is already live.
update public.offers set status = 'approved' where status = 'draft';

-- Fix 2. Owners write drafts and submit them; only Town Hub approves.
-- Editing an offer's terms sends it back for review, so an approved offer
-- can never be changed without Town Hub seeing it.
create or replace function public.guard_offer_write()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'authenticated' and not public.is_admin() then
    if tg_op = 'INSERT' then
      if new.status not in ('draft', 'submitted') then
        raise exception 'NOT_ALLOWED: offers must be approved by Town Hub' using errcode = '42501';
      end if;
      new.is_active := true;
      new.review_note := null;
      new.reviewed_at := null;
      new.reviewed_by := null;
    else
      if new.is_active is distinct from old.is_active
        or new.review_note is distinct from old.review_note
        or new.reviewed_at is distinct from old.reviewed_at
        or new.reviewed_by is distinct from old.reviewed_by
        or new.business_id is distinct from old.business_id then
        raise exception 'NOT_ALLOWED: only Town Hub can review offers' using errcode = '42501';
      end if;

      if (new.title, new.description, new.terms, new.offer_type, new.discount_value,
          new.starts_at, new.ends_at, new.monthly_limit, new.purchase_conditions, new.branch_id)
         is distinct from
         (old.title, old.description, old.terms, old.offer_type, old.discount_value,
          old.starts_at, old.ends_at, old.monthly_limit, old.purchase_conditions, old.branch_id) then
        if new.status not in ('draft', 'submitted') then
          new.status := 'submitted';
        end if;
      elsif new.status is distinct from old.status and new.status not in ('draft', 'submitted') then
        raise exception 'NOT_ALLOWED: offers must be approved by Town Hub' using errcode = '42501';
      end if;
    end if;

    if new.status = 'submitted' and (tg_op = 'INSERT' or old.status <> 'submitted') then
      new.submitted_at := now();
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists offers_guard_write on public.offers;
create trigger offers_guard_write
  before insert or update on public.offers
  for each row execute function public.guard_offer_write();

-- Owners keep insert/update (guarded above) but may delete only offers that
-- never went live, so redemption history can't be cascaded away.
drop policy if exists "offers_owner_manage" on public.offers;
create policy "offers_owner_insert"
  on public.offers for insert to authenticated
  with check (exists (select 1 from public.businesses b where b.id = business_id and b.owner_id = auth.uid()));
create policy "offers_owner_update"
  on public.offers for update to authenticated
  using (exists (select 1 from public.businesses b where b.id = business_id and b.owner_id = auth.uid()))
  with check (exists (select 1 from public.businesses b where b.id = business_id and b.owner_id = auth.uid()));
create policy "offers_owner_delete"
  on public.offers for delete to authenticated
  using (
    status in ('draft', 'rejected')
    and exists (select 1 from public.businesses b where b.id = business_id and b.owner_id = auth.uid())
    and not exists (select 1 from public.redemption_tokens t where t.offer_id = offers.id)
  );

-- Customers see only approved offers from eligible businesses.
drop policy if exists "offers_select_subscribed" on public.offers;
create policy "offers_select_subscribed"
  on public.offers for select to authenticated
  using (
    is_active
    and status = 'approved'
    and public.business_is_eligible(business_id)
    and exists (select 1 from public.profiles p where p.id = auth.uid() and p.is_subscribed)
  );

-- ---------------------------------------------------------------------
-- Vouchers: typeable code, snapshot of the terms, many-per-month limit
-- ---------------------------------------------------------------------
alter table public.redemption_tokens
  add column if not exists code text,
  add column if not exists offer_title text,
  add column if not exists offer_terms text;

create unique index if not exists redemption_tokens_code_key
  on public.redemption_tokens (code) where code is not null;

-- The limit is now per offer (offers.monthly_limit), so the fixed
-- one-per-month constraint goes. Each voucher still redeems at most once.
alter table public.redemptions
  drop constraint if exists redemptions_customer_id_offer_id_period_key;
create unique index if not exists redemptions_token_id_key
  on public.redemptions (token_id) where token_id is not null;

-- Serialises voucher issue and redemption for one customer + offer + month,
-- so two tills (or two taps) can't both slip under the monthly limit.
create or replace function public.lock_reward_allowance(p_customer uuid, p_offer uuid, p_period date)
returns void
language sql
as $$
  select pg_advisory_xact_lock(hashtextextended(p_customer::text || ':' || p_offer::text || ':' || p_period::text, 0));
$$;

-- 8 characters from a 32-letter alphabet without look-alikes (no I, O, 0, 1).
-- The bytes come from the first six bytes of a v4 UUID (fully random, and
-- built in — gen_random_bytes lives in Supabase's extensions schema) plus
-- two more from a second one. 32 divides 256, so every letter is equally
-- likely.
create or replace function public.new_voucher_code()
returns text
language plpgsql
as $$
declare
  alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  v_bytes bytea;
  v_code text;
begin
  loop
    v_bytes := substring(decode(replace(gen_random_uuid()::text, '-', ''), 'hex') from 1 for 6)
            || substring(decode(replace(gen_random_uuid()::text, '-', ''), 'hex') from 1 for 2);
    v_code := '';
    for i in 0..7 loop
      v_code := v_code || substr(alphabet, (get_byte(v_bytes, i) % 32) + 1, 1);
    end loop;
    exit when not exists (select 1 from public.redemption_tokens t where t.code = v_code);
  end loop;
  return v_code;
end;
$$;

-- Issues (or returns the customer's live) voucher for an offer. Called only
-- by the redeem-offer Edge Function. Raises one of: NOT_SUBSCRIBED,
-- PROFILE_INCOMPLETE, OFFER_UNAVAILABLE, ALREADY_REDEEMED.
create or replace function public.issue_voucher(p_customer uuid, p_offer uuid)
returns public.redemption_tokens
language plpgsql
security definer set search_path = public
as $$
declare
  v_period date := public.current_reward_period();
  v_profile public.profiles;
  v_offer public.offers;
  v_used integer;
  v_token public.redemption_tokens;
  v_expires timestamptz;
begin
  select * into v_profile from public.profiles where id = p_customer;
  if not found or not v_profile.is_subscribed then
    raise exception 'NOT_SUBSCRIBED';
  end if;
  if coalesce(trim(v_profile.full_name), '') = '' or coalesce(trim(v_profile.phone), '') = '' then
    raise exception 'PROFILE_INCOMPLETE';
  end if;

  perform public.lock_reward_allowance(p_customer, p_offer, v_period);

  select * into v_offer from public.offers
    where id = p_offer
      and is_active
      and status = 'approved'
      and (starts_at is null or starts_at <= now())
      and (ends_at is null or ends_at >= now());
  if not found or not public.business_is_eligible(v_offer.business_id) then
    raise exception 'OFFER_UNAVAILABLE';
  end if;

  select count(*) into v_used from public.redemptions
    where customer_id = p_customer and offer_id = p_offer and period = v_period;
  if v_used >= v_offer.monthly_limit then
    raise exception 'ALREADY_REDEEMED';
  end if;

  -- One live voucher at a time: asking again returns the same code rather
  -- than minting extra ones.
  select * into v_token from public.redemption_tokens
    where customer_id = p_customer and offer_id = p_offer and period = v_period
      and status = 'available' and expires_at > now()
    order by issued_at desc
    limit 1;
  if found then
    return v_token;
  end if;

  update public.redemption_tokens set status = 'expired'
    where customer_id = p_customer and offer_id = p_offer
      and status = 'available' and (expires_at <= now() or period <> v_period);

  -- Valid to the end of this month (SA time), or the offer's end if sooner.
  v_expires := (v_period + interval '1 month')::timestamp at time zone 'Africa/Johannesburg';
  if v_offer.ends_at is not null and v_offer.ends_at < v_expires then
    v_expires := v_offer.ends_at;
  end if;

  insert into public.redemption_tokens
    (customer_id, business_id, offer_id, period, status, expires_at, code, offer_title, offer_terms)
  values
    (p_customer, v_offer.business_id, p_offer, v_period, 'available', v_expires,
     public.new_voucher_code(), v_offer.title, v_offer.terms)
  returning * into v_token;
  return v_token;
end;
$$;

-- Fix 3. Verifies and (unless p_dry_run) redeems a voucher in a single
-- transaction: the token is locked, re-checked, marked used and recorded
-- together, so a failure leaves nothing half-done and two staff can't both
-- succeed. Called only by the approve-redemption Edge Function.
create or replace function public.redeem_voucher(
  p_token uuid,
  p_business uuid,
  p_staff uuid,
  p_dry_run boolean
)
returns table (result text, offer_title text, customer_name text, voucher_code text, redeemed_at timestamptz)
language plpgsql
security definer set search_path = public
as $$
#variable_conflict use_column
declare
  v_token public.redemption_tokens;
  v_offer public.offers;
  v_customer public.profiles;
  v_used integer;
  v_now timestamptz := now();
begin
  select * into v_token from public.redemption_tokens where id = p_token;
  if not found then
    return query select 'INVALID_TOKEN'::text, null::text, null::text, null::text, null::timestamptz;
    return;
  end if;

  perform public.lock_reward_allowance(v_token.customer_id, v_token.offer_id, v_token.period);
  select * into v_token from public.redemption_tokens where id = p_token for update;

  if v_token.business_id <> p_business then
    return query select 'WRONG_BUSINESS'::text, null::text, null::text, null::text, null::timestamptz;
    return;
  end if;
  if not public.business_is_eligible(p_business) then
    return query select 'BUSINESS_INELIGIBLE'::text, null::text, null::text, null::text, null::timestamptz;
    return;
  end if;
  if v_token.status = 'used' then
    return query select 'ALREADY_USED'::text, v_token.offer_title, null::text, v_token.code, v_token.used_at;
    return;
  end if;
  if v_token.status = 'expired' or v_token.expires_at < v_now
     or v_token.period <> public.current_reward_period() then
    return query select 'EXPIRED'::text, v_token.offer_title, null::text, v_token.code, null::timestamptz;
    return;
  end if;

  select * into v_offer from public.offers where id = v_token.offer_id;
  if not found or not v_offer.is_active or v_offer.status <> 'approved'
     or (v_offer.starts_at is not null and v_offer.starts_at > v_now)
     or (v_offer.ends_at is not null and v_offer.ends_at < v_now) then
    return query select 'OFFER_INACTIVE'::text, v_token.offer_title, null::text, v_token.code, null::timestamptz;
    return;
  end if;

  select * into v_customer from public.profiles where id = v_token.customer_id;
  if not found or not v_customer.is_subscribed then
    return query select 'NOT_SUBSCRIBED'::text, v_token.offer_title, null::text, v_token.code, null::timestamptz;
    return;
  end if;

  select count(*) into v_used from public.redemptions
    where customer_id = v_token.customer_id and offer_id = v_token.offer_id and period = v_token.period;
  if v_used >= v_offer.monthly_limit then
    return query select 'LIMIT_REACHED'::text, v_token.offer_title, v_customer.full_name, v_token.code, null::timestamptz;
    return;
  end if;

  if p_dry_run then
    return query select 'VALID'::text, v_token.offer_title, v_customer.full_name, v_token.code, null::timestamptz;
    return;
  end if;

  update public.redemption_tokens
    set status = 'used', used_at = v_now, used_by = p_staff
    where id = v_token.id;
  insert into public.redemptions (token_id, customer_id, business_id, offer_id, period, redeemed_at, approved_by)
    values (v_token.id, v_token.customer_id, v_token.business_id, v_token.offer_id, v_token.period, v_now, p_staff);

  return query select 'VALID'::text, v_token.offer_title, v_customer.full_name, v_token.code, v_now;
end;
$$;

-- Only the Edge Functions (service role) may issue or redeem vouchers.
revoke execute on function public.issue_voucher(uuid, uuid) from public, anon, authenticated;
revoke execute on function public.redeem_voucher(uuid, uuid, uuid, boolean) from public, anon, authenticated;
revoke execute on function public.lock_reward_allowance(uuid, uuid, date) from public, anon, authenticated;
revoke execute on function public.new_voucher_code() from public, anon, authenticated;
grant execute on function public.issue_voucher(uuid, uuid) to service_role;
grant execute on function public.redeem_voucher(uuid, uuid, uuid, boolean) to service_role;

-- =====================================================================
-- 0012_admin_memberships.sql
-- =====================================================================
-- Town Hub admin: manage customer memberships from the app. Apply after 0011.
--
-- Until now is_subscribed could only be changed in the SQL Editor:
-- authenticated users may update only their own name/avatar/town/phone
-- (column grants in 0007/0008), and auth.users — where emails live — isn't
-- readable from the app at all. These two functions give admins exactly
-- what the Members page needs and nothing more. Both check is_admin()
-- themselves, so calling them as anyone else fails.

-- Members matching a name, email or phone search (all members if blank),
-- newest first.
create or replace function public.admin_list_members(p_search text default null, p_limit integer default 100)
returns table (
  id uuid,
  full_name text,
  email text,
  phone text,
  home_town text,
  role text,
  is_subscribed boolean,
  created_at timestamptz
)
language plpgsql
stable
security definer set search_path = public
as $$
declare
  q text := nullif(trim(coalesce(p_search, '')), '');
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED' using errcode = '42501';
  end if;

  return query
    select p.id, p.full_name, u.email::text, p.phone, p.home_town, p.role::text, p.is_subscribed, p.created_at
    from public.profiles p
    join auth.users u on u.id = p.id
    where q is null
       or p.full_name ilike '%' || q || '%'
       or u.email ilike '%' || q || '%'
       or p.phone ilike '%' || q || '%'
    order by p.created_at desc
    limit least(greatest(coalesce(p_limit, 100), 1), 500);
end;
$$;

-- Switches one member's rewards membership on or off.
create or replace function public.admin_set_membership(p_user uuid, p_subscribed boolean)
returns void
language plpgsql
security definer set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED' using errcode = '42501';
  end if;

  update public.profiles set is_subscribed = p_subscribed where id = p_user;
  if not found then
    raise exception 'MEMBER_NOT_FOUND';
  end if;
end;
$$;

revoke execute on function public.admin_list_members(text, integer) from public, anon;
revoke execute on function public.admin_set_membership(uuid, boolean) from public, anon;
grant execute on function public.admin_list_members(text, integer) to authenticated;
grant execute on function public.admin_set_membership(uuid, boolean) to authenticated;

-- ---------------------------------------------------------------------
-- Part 3: live voucher status
-- ---------------------------------------------------------------------
-- QRDisplay subscribes to changes on the customer's voucher row; Supabase
-- only broadcasts tables in the supabase_realtime publication.
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (
       select 1 from pg_publication_tables
       where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'redemption_tokens'
     ) then
    alter publication supabase_realtime add table public.redemption_tokens;
  end if;
end;
$$;

commit;

